import{_ as l,l as i,o as e,c as n,v as t,p as s,x as r,d as E,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"内存标签 MTE","description":"","frontmatter":{"title":"内存标签 MTE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-tagging.md","filePath":"cs/memory-tagging.md","lastUpdated":1789023840000}'),A={name:"cs/memory-tagging.md"};function m(p,a,h,T,_,g){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="内存标签-mte" tabindex="-1">内存标签 MTE <a class="header-anchor" href="#内存标签-mte" aria-label="Permalink to &quot;内存标签 MTE&quot;">​</a></h1><div class="epigraph"><p>MTE 给指针和内存块各存一小组标签，访问时硬件比较，对不上则故障，从而在运行时抓住空间错误。</p><footer>—— 据 ARM 对 Memory Tagging Extension 的说明；Linux 对 MTE 的文档</footer></div><p><a href="/cs/dma-coherence">上一课</a>留下的缺口接到本课。 <a href="/cs/kernel-hardening">加固</a> 的金丝雀只护栈边界。<a href="/cs/asan-mechanism">ASan</a> 后课用影子内存，税更高。缺口是 <strong>硬件标签</strong>：ARM MTE 在 OS 如何启用、与分配器接头。不是 SPARC ADI 的百科，但同族。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>堆溢出、UAF：指针仍指向可写框。MTE：16 字节粒度标签，指针上位或专用字段带 tag，逻辑与物理标签比较。缺口：内核 <code>kasan</code> 硬件模式、用户 <code>PR_SET_TAGGED_ADDR</code>、与 <a href="/cs/malloc-implementation">malloc</a> 必须在释放时换标签。本课不把 Intel LAM 的全部等价物写完。</p><p><span class="marginnote">同步 vs 异步检查影响延迟与精度。标签位数有限，碰撞可能漏。不是形式证明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>mmap 匿名区可标 MTE。分配器：取页，随机 tag，指针染色。free：改内存 tag，悬垂指针不再匹配。对照 <a href="/cs/userfaultfd">userfaultfd</a>：一个填内容，一个查标签。对照 KPTI：一个隔离内核映射，一个隔离对象代。</p>',8)),(e(),s(c,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALLOC%5B%22%E5%88%86%E9%85%8D%22%5D%20--%3E%20TAG%5B%22%E5%86%85%E5%AD%98%E4%B8%8E%E6%8C%87%E9%92%88%E5%90%8C%E6%A0%87%E7%AD%BE%22%5D%0A%20%20ACCESS%5B%22load%2Fstore%22%5D%20--%3E%20CMP%5B%22%E7%A1%AC%E4%BB%B6%E6%AF%94%E6%A0%87%E7%AD%BE%22%5D%0A%20%20CMP%20--%3E%7C%22%E5%90%A6%22%7C%20FAULT%5B%22%E5%90%8C%E6%AD%A5%E6%88%96%E5%BC%82%E6%AD%A5%E5%BC%82%E5%B8%B8%22%5D%0A%20%20FREE%5B%22%E9%87%8A%E6%94%BE%22%5D%20--%3E%20RETAG%5B%22%E6%8D%A2%E5%86%85%E5%AD%98%E6%A0%87%E7%AD%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MTE 把空间安全从纯软件插桩变成 CPU 检查，税低于完整 ASan，覆盖粒度粗于 byte-ASan。OS 负责：页表属性、信号、coredump 里的 tag 状态。不要写成类型系统课。与 DMA：设备一般不带 tag，设备路径要绕或用未染色地址。</p><p>部署：用户态可逐步开；内核 KASAN 硬件模式服务开发内核。</p><p>实现上：标签 4 位则 16 分之一碰撞漏检。异步模式把故障推迟，难归因。内核与用户标签空间要配置，指针切片（PAC）是另一套硬件，不要混。 读法上只引用<a href="/cs/dma-coherence">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>内存标签 MTE</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每种 libc 的 MTE 默认。不保证虚拟机把 MTE 传给客户。下一课用户态堆：malloc 实现。</p><p>版本字段会变，课序钉的是机制对象「内存标签 MTE」，不是某一主线内核的结构体名。 后课默认：硬件可对指针染色查越界/UAF。malloc 如何切 arena 与空闲链，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MTE 用标签匹配检测空间错误。</li><li>分配器释放必须换标签。</li><li>malloc 实现是下一课。</li><li>出处：ARM MTE；Linux tagged address；KASAN 文档。</li></ul>',11))])}const M=l(A,[["render",m]]);export{f as __pageData,M as default};
